const tile=(title,sub='',n='',delay=0)=>`<div class="tile">${n?`<div class="big-index">${n}</div>`:''}<strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</div>`;
const flow=(items)=>`<div class="flow">${items.map((x,i)=>tile(x[0],x[1],String(i+1).padStart(2,'0'),i*4200)).join('')}</div>`;
const rows=(items)=>`<div class="rows ${items.length===4?'four':''}">${items.map((x,i)=>tile(x[0],x[1],x[2]||'',i*3800)).join('')}</div>`;
const scenes=[
{id:'overview',theme:'dark',title:'Build a world. Make it useful.',html:`<div class="hero"><div><h1>Build a world.<br> <em>Make it useful.</em></h1><p>Turn a subject you care about into a place you can explore.</p><a class="pill-link" href="https://wintry-soul-6awh.here.now/" target="_blank" rel="noopener">Explore Inside Codex ↗</a></div><figure><img src="assets/world.png" alt="The actual Inside Codex world and its animated guide" width="1440" height="900" fetchpriority="high"></figure></div><div class="route"><span>Idea</span><i>→</i><span>Plan</span><i>→</i><span>Build</span><i>→</i><span>Host</span></div>`},
{id:'build',theme:'dark',title:'Then let it build.',html:`<div class="split"><div><div class="fact">≈18<small> hours</small></div><p class="fact-label">For this full world.</p><div class="word-list"><span>Build</span><span>Test</span><span>Refine</span></div><p class="tiny">Main production: 17h 24m through version 0.1.0.<br>Later walkthrough and answer controls are separate.</p></div><div class="stack">${tile('Start with one scene','Make scope fit the usage you have.','',0)}${tile('Check your allowance','Plan, effort and workload affect usage.','',4200)}${tile('Inspect before expanding','Repair one lesson before copying the pattern.','',8400)}</div></div>`},
{id:'host',theme:'purple',title:'Put your world online.',html:`<div class="prompt-box"><p id="host-prompt">Build the production version of this project and publish its output with here.now. Use a permanent site under my account, help me complete sign-in if needed, then open the live URL and verify the world, its assets and the download links.</p><button id="copy-host">Copy deployment prompt</button></div><div class="route"><span>Install skill</span><i>→</i><span>Sign in</span><i>→</i><span>Publish</span><i>→</i><span>Open link</span></div><p class="source-line"><a href="https://here.now/docs" target="_blank" rel="noopener">here.now documentation ↗</a> · Anonymous links expire after 24 hours.</p>`},
{id:'possibilities',theme:'cyan',title:'Choose your own subject.',html:`<div class="rows"><a class="tile link-panel" href="https://model-x-studio.vercel.app/" target="_blank" rel="noopener"><div class="big-index">01</div><strong>Engineering <span class="arrow">↗</span></strong><small>Explore a Tesla Model X.<br>Built by ashe.</small></a><a class="tile link-panel" href="https://human-atlas-seven.vercel.app/" target="_blank" rel="noopener"><div class="big-index">02</div><strong>Anatomy <span class="arrow">↗</span></strong><small>Explore the Human Atlas.<br>Built by ashe.</small></a><a class="tile link-panel" href="https://silicon-quest-kappa.vercel.app/" target="_blank" rel="noopener"><div class="big-index">03</div><strong>Chip design <span class="arrow">↗</span></strong><small>Explore Silicon Quest.<br>Built by Georgia Witchel.</small></a></div>`},
{id:'resources',theme:'dark',title:'Start with the actual plan.',html:`<div class="comparison"><a class="tile link-panel" href="downloads/Learning-World-Starter-Kit.zip" download><div class="big-index">↓</div><strong>Planning kit</strong><small>The original plan.<br>A starting prompt.<br>A Blender + hosting guide.</small></a><div class="tile"><strong>Community source code</strong><div class="check-lines"><span>Classroom</span><span>Claude Code Living</span><span>Claude and Codex Systems</span></div></div></div>`}
];
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const readable=s=>marked.parseInline(s);
scenes.splice(1,0,...planAnnotations.map((a,i)=>({id:`plan-${String(i+1).padStart(2,'0')}`,theme:i%2?'purple':'cyan',title:a.title,html:`<div class="annotation-sheet"><div class="annotation-header"><span>Original plan · §${i+1}</span><span>Why this instruction is here</span></div>${a.notes.map((n,j)=>`<div class="annotation-pair"><blockquote><span class="annotation-number">${j+1}</span><p>${readable(n.quote)}</p></blockquote><aside><strong>${esc(n.label)}</strong><p>${esc(n.why)}</p></aside></div>`).join('')}</div><a class="full-section" href="plan.html#section-${i+1}" target="_blank">Read this entire section, annotated ↗</a>`})));
const root=document.querySelector('#slides');root.innerHTML=scenes.map((s,i)=>`<section id="${s.id}" class="scene ${s.theme} ${s.id.startsWith('plan-')?'annotated':''} ${s.id==='possibilities'?'subject-list':''} ${i===0?'active':''}" data-index="${i}" aria-label="${esc(s.title)}">${i?`<h2>${esc(s.title)}</h2>`:''}<div class="visual">${s.html}</div></section>`).join('');
document.querySelector('#scene-links').innerHTML=scenes.map((s,i)=>`<a href="#${s.id}">${String(i+1).padStart(2,'0')} · ${esc(s.title)}</a>`).join('');
const sections=[...root.children];let active=0,scrollTimer;
function activate(i){sections[active].classList.remove('active');active=i;sections[i].classList.add('active');document.querySelector('#counter').textContent=`${String(i+1).padStart(2,'0')} / ${scenes.length}`;document.querySelector('#source').hidden=!(i>=1&&i<=15)}
function settle(){let best=0,dist=Infinity;sections.forEach((s,i)=>{const d=Math.abs(s.getBoundingClientRect().top);if(d<dist){best=i;dist=d}});activate(best)}
addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(settle,80)},{passive:true});
document.querySelector('#hide').onclick=()=>document.body.classList.toggle('hide-chrome');
addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,dialog')||e.metaKey||e.ctrlKey||e.altKey)return;if(e.key.toLowerCase()==='h'){e.preventDefault();document.body.classList.toggle('hide-chrome')}});
document.querySelector('#open-scenes').onclick=()=>document.querySelector('#scene-menu').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('#scene-links a').forEach(a=>a.onclick=()=>document.querySelector('#scene-menu').close());
document.querySelector('#source').onclick=()=>{const p=originalPlan[active-1];document.querySelector('#source-title').textContent=p.heading;document.querySelector('#source-text').innerHTML=marked.parse(p.text);document.querySelector('#source-dialog').showModal()};
document.querySelector('#copy-host').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#host-prompt').textContent);document.querySelector('#copy-host').textContent='Copied'}catch{document.querySelector('#copy-host').textContent='Select the prompt to copy'}};
window.filming={scenes:scenes.map(s=>({id:s.id,title:s.title})),go:i=>{sections[i].scrollIntoView({behavior:'instant'});activate(i)}};
addEventListener('load',settle);
